<?php
namespace App\Http\Controllers;
use App\Models\AttendanceCorrection; use App\Models\AttendanceRecord; use App\Services\WorkforceAuditService; use Illuminate\Http\Request; use Illuminate\Support\Facades\DB;
class AttendanceCorrectionController extends Controller {
 public function store(Request $r, AttendanceRecord $attendance){$d=$r->validate(['requested_clock_in_at'=>'nullable|date','requested_clock_out_at'=>'nullable|date|after:requested_clock_in_at','reason'=>'required|string|max:1000']);$employeeId=auth()->user()->employee_id ?: $attendance->employee_id; abort_unless((int)$employeeId===(int)$attendance->employee_id || auth()->user()->hasAnyRole(['super_admin','admin_group','unit_manager']),403);$d+=['attendance_record_id'=>$attendance->id,'employee_id'=>$attendance->employee_id,'requested_by'=>auth()->id()];AttendanceCorrection::create($d);return back()->with('success','Attendance correction submitted for review.');}
 public function decide(Request $r, AttendanceCorrection $correction, WorkforceAuditService $audit){$d=$r->validate(['action'=>'required|in:approve,reject','review_note'=>'nullable|string|max:1000']);$old=$correction->toArray();DB::transaction(function()use($correction,$d){$correction->update(['status'=>$d['action']==='approve'?'approved':'rejected','reviewed_by'=>auth()->id(),'reviewed_at'=>now(),'review_note'=>$d['review_note']??null]);if($d['action']==='approve'){$record=$correction->attendanceRecord;$values=[];if($correction->requested_clock_in_at)$values['clock_in_at']=$correction->requested_clock_in_at;if($correction->requested_clock_out_at)$values['clock_out_at']=$correction->requested_clock_out_at;if(isset($values['clock_in_at'],$values['clock_out_at']))$values['worked_minutes']=(int)round((strtotime($values['clock_out_at'])-strtotime($values['clock_in_at']))/60);$values['verified_by']=auth()->id();$values['verified_at']=now();$values['is_exception']=false;$record->update($values);}});$audit->model('updated',$correction,'Attendance correction decision',$old);return back()->with('success','Attendance correction decision recorded.');}
}
